/*! coi-serviceworker v0.1.7 - Guido Zuidhof and contributors, licensed under MIT
 * Rock N Roller fork: isolate player documents only.
 *
 * GitHub Pages cannot send COOP/COEP, so this worker injects them for
 * SharedArrayBuffer/pthreads. Scope is origin-wide (/) because the script
 * lives at the site root. Without a path check, EVERY document — including
 * the landing page YouTube embed — gets COEP: require-corp. YouTube does
 * not send CORP, so the iframe shows "unable to load" until a hard refresh
 * bypasses the worker. Regular reload still goes through the worker.
 *
 * Isolation headers are applied only to player documents:
 *   /latest/  and  /<semver>/  (same match as 404.html)
 * Same-origin subresources still get CORP so isolated player pages can load
 * /assets/*. Content pages (/ , /features/, …) pass through un-isolated.
 */
let coepCredentialless = false;

function isPlayerPath(pathname) {
  const first = pathname.split("/").filter(Boolean)[0] || "";
  if (first === "latest") return true;
  return /^[0-9]+\.[0-9]+(\.[0-9A-Za-z.-]+)?$/.test(first);
}

function isDocumentRequest(request) {
  return request.mode === "navigate" || request.destination === "document";
}

if (typeof window === "undefined") {
  self.addEventListener("install", () => self.skipWaiting());
  self.addEventListener("activate", (event) =>
    event.waitUntil(self.clients.claim()),
  );

  self.addEventListener("message", (ev) => {
    if (!ev.data) {
      return;
    } else if (ev.data.type === "deregister") {
      self.registration
        .unregister()
        .then(() => {
          return self.clients.matchAll();
        })
        .then((clients) => {
          clients.forEach((client) => client.navigate(client.url));
        });
    } else if (ev.data.type === "coepCredentialless") {
      coepCredentialless = ev.data.value;
    }
  });

  self.addEventListener("fetch", function (event) {
    const r = event.request;
    if (r.cache === "only-if-cached" && r.mode !== "same-origin") {
      return;
    }

    const request =
      coepCredentialless && r.mode === "no-cors"
        ? new Request(r, {
            credentials: "omit",
          })
        : r;
    event.respondWith(
      fetch(request)
        .then((response) => {
          if (response.status === 0) {
            return response;
          }

          const newHeaders = new Headers(response.headers);
          const isolate =
            isDocumentRequest(request) &&
            isPlayerPath(new URL(request.url).pathname);

          if (isolate) {
            newHeaders.set(
              "Cross-Origin-Embedder-Policy",
              coepCredentialless ? "credentialless" : "require-corp",
            );
            newHeaders.set("Cross-Origin-Opener-Policy", "same-origin");
          }

          if (!coepCredentialless || !isolate) {
            newHeaders.set("Cross-Origin-Resource-Policy", "cross-origin");
          }

          return new Response(response.body, {
            status: response.status,
            statusText: response.statusText,
            headers: newHeaders,
          });
        })
        .catch((e) => console.error(e)),
    );
  });
} else {
  (() => {
    const reloadedBySelf = window.sessionStorage.getItem("coiReloadedBySelf");
    window.sessionStorage.removeItem("coiReloadedBySelf");
    const coepDegrading = reloadedBySelf == "coepdegrade";

    const coi = {
      shouldRegister: () => !reloadedBySelf,
      shouldDeregister: () => false,
      coepCredentialless: () => true,
      coepDegrade: () => true,
      doReload: () => window.location.reload(),
      quiet: false,
      ...window.coi,
    };

    const n = navigator;
    const controlling = n.serviceWorker && n.serviceWorker.controller;

    if (controlling && !window.crossOriginIsolated) {
      window.sessionStorage.setItem("coiCoepHasFailed", "true");
    }
    const coepHasFailed = window.sessionStorage.getItem("coiCoepHasFailed");

    if (controlling) {
      const reloadToDegrade =
        coi.coepDegrade() && !(coepDegrading || window.crossOriginIsolated);
      n.serviceWorker.controller.postMessage({
        type: "coepCredentialless",
        value:
          reloadToDegrade || (coepHasFailed && coi.coepDegrade())
            ? false
            : coi.coepCredentialless(),
      });
      if (reloadToDegrade) {
        !coi.quiet && console.log("Reloading page to degrade COEP.");
        window.sessionStorage.setItem("coiReloadedBySelf", "coepdegrade");
        coi.doReload("coepdegrade");
      }

      if (coi.shouldDeregister()) {
        n.serviceWorker.controller.postMessage({ type: "deregister" });
      }
    }

    if (window.crossOriginIsolated !== false || !coi.shouldRegister()) return;

    if (!window.isSecureContext) {
      !coi.quiet &&
        console.log(
          "COOP/COEP Service Worker not registered, a secure context is required.",
        );
      return;
    }

    if (!n.serviceWorker) {
      !coi.quiet &&
        console.error(
          "COOP/COEP Service Worker not registered, perhaps due to private mode.",
        );
      return;
    }

    n.serviceWorker.register(window.document.currentScript.src).then(
      (registration) => {
        !coi.quiet &&
          console.log("COOP/COEP Service Worker registered", registration.scope);

        registration.addEventListener("updatefound", () => {
          !coi.quiet &&
            console.log(
              "Reloading page to make use of updated COOP/COEP Service Worker.",
            );
          window.sessionStorage.setItem("coiReloadedBySelf", "updatefound");
          coi.doReload();
        });

        if (registration.active && !n.serviceWorker.controller) {
          !coi.quiet &&
            console.log("Reloading page to make use of COOP/COEP Service Worker.");
          window.sessionStorage.setItem("coiReloadedBySelf", "notcontrolling");
          coi.doReload();
        }
      },
      (err) => {
        !coi.quiet &&
          console.error("COOP/COEP Service Worker failed to register:", err);
      },
    );
  })();
}
